class Solution:
    def generate_parenthesis(self, n: int) -> List[str]:
        res, path = [], []

        def build(open_: int, close: int) -> None:
            if len(path) == 2 * n:
                res.append("".join(path))
                return
            if open_ < n:
                path.append('(')
                build(open_ + 1, close)
                path.pop()
            if close < open_:
                path.append(')')
                build(open_, close + 1)
                path.pop()

        build(0, 0)
        return res
```

