class Solution:
    def find_median_sorted_arrays(self, a: List[int], b: List[int]) -> float:
        if len(a) > len(b):
            a, b = b, a
        m, n = len(a), len(b)
        half, lo, hi = (m + n + 1) // 2, 0, m
        inf = float('inf')
        while lo <= hi:
            i = (lo + hi) // 2
            j = half - i
            a_l = a[i - 1] if i > 0 else -inf
            a_r = a[i] if i < m else inf
            b_l = b[j - 1] if j > 0 else -inf
            b_r = b[j] if j < n else inf
            if a_l <= b_r and b_l <= a_r:
                if (m + n) % 2:
                    return float(max(a_l, b_l))
                return (max(a_l, b_l) + min(a_r, b_r)) / 2
            if a_l > b_r:
                hi = i - 1
            else:
                lo = i + 1
        return 0.0
```

